    "從目標出發，經過講解、練習和調整，需要時再複習，一步步把能力練出來。",
  "landing.body.006": "目標",
  "landing.body.007": "講解",
  "landing.body.008": "練習",
  "landing.body.009": "調整",
  "landing.body.010": "復習",
  "landing.body.011": "形成能力",
  "landing.body.012": "學得順就繼續，卡住了就換條路，忘了的內容之後再回來練",
  "landing.body.013": "一節課的流程",
  "landing.body.014": "從預習到複習，看看一節課都經過哪些環節",
  "landing.body.015": "小測不只為打分",
  "landing.body.016": "每次小測都會影響接下來的講解和練習",
  "landing.body.017":
    "一次回答能看出：是你自己做的，還是靠了提示；過一陣子，還記不記得。",
  "landing.body.018": "隨文追問",
  "landing.body.019": "哪句沒看懂，就在那句旁邊問",
  "landing.body.020":
    "選中看不懂的那句，讓助教換個例子、打個比方，或者看看你錯在哪。原文和進度會一起帶進問題，不用重新解釋。",
  "landing.body.021": "正文講解",
  "landing.body.022": "學習中",
  "landing.body.023": "為什麼要隔段時間複習？",
  "landing.body.024":
    "與其一口氣反覆看很多遍，不如在快忘的時候再回想一次。每回想成功一次，之後記得就更久。",
  "landing.body.025": "“在快忘的時候，再回想一次”",
  "landing.body.026": "追問",
  "landing.body.027": "針對這段內容追問",
  "landing.body.028": "能用一個工作中的例子解釋嗎？",
  "landing.body.029": "AI 助教",
  "landing.body.030":
    "就像練習演講：連續講五遍看似熟練，但隔兩天再講一次，更能檢驗你是否真的記住了結構……",
  "landing.body.031": "學到的，要能用出來",
  "landing.body.032": "有的要開口說，有的要在情境裡做選擇",
  "landing.body.033":
    "有些內容適合邊聊邊學，有些得放進真實場景裡練。哪種方式合適，我們按內容來定。",
  "landing.body.034": "對話式學習",
  "landing.body.035": "講一小段，問一句，再接著往下",
  "landing.body.036":
    "內容會拆成幾個小段，講一段、問一句。隨時可以追問、回看或換一節，不用在長文和聊天框之間來回跳。",
  "landing.body.037": "第 2 節 · 建立可靠的復習節奏",
  "landing.body.038": "本節旅程",
  "landing.body.039": "為什麼會忘",
  "landing.body.040": "什麼時候再練",
  "landing.body.041": "快速自測",
  "landing.body.042": "小會 · AI 學習助教",
  "landing.body.043":
    "在記憶開始變淡時再回想一次，往往比短時間內連續重複更有效。",
  "landing.body.044": "那我要怎樣判斷“快要忘記”？",
  "landing.body.045":
    "靠感覺很難判斷，所以我們會根據你之前的回答和間隔的時間，幫你安排下一次回想……",
  "landing.body.046": "點擊繼續對話",
  "landing.body.047": "會學劇場 · 情境演練",
  "landing.body.048": "遇到具體局面時，你會怎麼選？",
  "landing.body.049":
    "在適合演練的課程裡，你會面對角色、目標和一連串決定。選完以後，看看局面會怎麼變化。",
  "landing.body.050": "項目會議 · 第 3 幕",
  "landing.body.051": "你的選擇會改變後續",
  "landing.body.052": "林",
  "landing.body.053":
    "客戶臨時要求提前一周上線，但團隊已經連續加班。你準備怎樣回應？",
  "landing.body.054": "團隊信任",
  "landing.body.055":
    "對話模式適合系統學完整門課；需要臨場判斷的內容，會放進劇場裡練。",
  "landing.body.056": "給下班後還想認真學點東西的人",
  "landing.body.057": "說說你想學會什麼，",
  "landing.body.058": "我們幫你把這件事一步步學下來",
  "landing.body.059":
    "先弄清楚你的目標和基礎，再排好課程、練習和複習。學到哪了都記得，下次回來接著學。",
  "landing.body.060": "適合那些要花幾週或幾個月，才能慢慢學成的事。",
  "landing.body.061": "看看它是怎麼學的",
  "landing.body.062": "聊天答疑之後，怎麼繼續學？",
  "landing.body.063": "好會學會記住這次進度，下次接著往前走",
  "landing.body.064":
    "聊天工具很適合臨時答疑。好會學會記住你的目標、課程和練習情況，下次回來接著學。",
  "landing.body.065": "比較",
  "landing.body.066": "普通對話 AI",
  "landing.body.067": "好會學",
  "landing.body.068": "它是怎麼學的",
  "landing.body.069": "先從眼前這一節開始",
  "landing.body.070":
    "告訴我們你想學什麼、現在會什麼。剩下的交給我們：先排出一條路，你從眼前這一節開始。",
  "landing.body.071": "學一節，練一節",
  "landing.body.072": "講完就練，沒懂可以當場問",
  "landing.body.073":
    "每節都有預習要點、正文和小練習。答錯了，當場弄清楚錯在哪，再繼續往下學。",
  "landing.body.074": "怎麼算學會？",
  "landing.body.075": "看你能不能獨立做出來",
  "landing.body.076":
    "我們更在意你能不能獨立做出來。靠提示完成、換個題不會、過幾天忘了，都說明還要再練練。",
  "landing.body.077": "什麼時候會調整課程",
  "landing.body.078": "適合什麼樣的目標",
  "landing.body.079": "適合需要長期投入的目標",
  "landing.body.080":
    "比如轉崗要補的技能、想做出來的專案，或一直想系統了解的興趣。通常要花幾週到幾個月。",
  "landing.body.081": "可以先免費試試",
  "landing.body.082": "最近有什麼事，你一直想學卻沒開始？",
  "landing.body.083": "先寫一句話就行。基礎、時間和資料，下一步再慢慢補。",
  "landing.body.084": "就學這個",
  "landing.body.085": "好會學 · 把想學的事，一步步學下來",
  "landing.body.086": "法律與備案信息",
