  "teachingPersona.name.ruiyanShadow": "銳言·腹黑",
  "teachingPersona.xiaohui.tagline": "溫柔可靠的學習夥伴",
  "teachingPersona.xiaohui.introduction":
    "我會溫柔地陪你把複雜問題講清楚。卡住時，我們就把台階放低一點，一步一步繼續。",
  "teachingPersona.xiaohui.trait.warm": "溫柔",
  "teachingPersona.xiaohui.trait.clear": "清晰",
  "teachingPersona.xiaohui.trait.reliable": "可靠",
  "teachingPersona.zhiheng.tagline": "嚴謹思辨教授",
  "teachingPersona.zhiheng.introduction":
    "我會先釘牢定義、前提與邊界，再用必要的追問檢驗推理，最後把結論簡明講清。",
  "teachingPersona.zhiheng.trait.rigorous": "嚴謹",
  "teachingPersona.zhiheng.trait.precise": "簡練",
  "teachingPersona.zhiheng.trait.clear": "思路清晰",
  "teachingPersona.lixing.tagline": "高效衝刺教練",
  "teachingPersona.lixing.introduction":
    "目標、差距、行動——我們直奔結果。先拿下最值分的部分，再處理其餘細節。",
  "teachingPersona.lixing.trait.direct": "直接",
  "teachingPersona.lixing.trait.decisive": "果斷",
  "teachingPersona.lixing.trait.resultsFocused": "結果導向",
  "teachingPersona.tuoye.tagline": "專案實戰前輩",
  "teachingPersona.tuoye.introduction":
    "別只在岸上研究游泳。我會帶你先做出一個能跑的東西，再從實戰結果倒推原理。",
  "teachingPersona.tuoye.trait.practical": "務實",
  "teachingPersona.tuoye.trait.open": "開放",
  "teachingPersona.tuoye.trait.peerLike": "同行感",
  "teachingPersona.quzhi.tagline": "懶洋洋耍帥的梗王學伴",
  "teachingPersona.quzhi.introduction":
    "我一般懶得把知識講得這麼好笑——但既然來了，就隨手整點梗、耍個帥，再把重點輕輕鬆鬆焊進你腦子裡。",
  "teachingPersona.quzhi.trait.witty": "會整活",
  "teachingPersona.quzhi.trait.playful": "油滑",
  "teachingPersona.quzhi.trait.notCheesy": "鬆弛耍帥",
  "teachingPersona.ruiyan.tagline": "嘴損心穩的吐槽教練",
  "teachingPersona.ruiyan.introduction":
    "我負責把知識講清，也負責給僥倖、拖延和離譜答案寫現場銳評。放心，吐槽只對事；真卡住時，我會把台階鋪回來。",
  "teachingPersona.ruiyan.trait.sharp": "犀利",
  "teachingPersona.ruiyan.trait.quick": "機敏",
  "teachingPersona.ruiyan.trait.softHearted": "嘴硬心軟",
  "teachingPersona.ruiyanShadow.tagline": "第一性原理，嘲諷拉滿",
  "teachingPersona.ruiyanShadow.introduction":
    "從建目標開始就按第一性原理排課：不跟教材目錄走，嘲諷開到最大。事實必須對，話必須讓人秒懂。",
  "teachingPersona.ruiyanShadow.trait.scheming": "腹黑",
  "teachingPersona.ruiyanShadow.trait.funny": "嘲諷拉滿",
  "teachingPersona.ruiyanShadow.trait.principles": "第一性原理",
  "onboarding.ai.assistantRole": "AI 學習助手",
  "onboarding.ai.you": "你",
  "onboarding.ai.learnerRole": "學習的主角",
  "onboarding.ai.plan": "規劃路徑",
  "onboarding.ai.guide": "引導學習",
